import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, STYLE } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const COUNT = 4;
// Each tile grows out of its own outer corner: top-left, top-right, bottom-left, bottom-right.
const ORIGINS = ["0% 0%", "100% 0%", "0% 100%", "100% 100%"];

const GrelhaQuatroFotos: React.FC<PrimitiveProps> = ({ anim, fps, frame }) => {
  const f = useCurrentFrame();
  const params = (anim.params ?? {}) as Record<string, unknown>;
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const base = Math.min(frame.width, frame.height);

  // `src` is the pipeline's slot; src2..src4 (or a srcs array) carry the rest.
  const list = Array.isArray(params.srcs) ? (params.srcs as unknown[]) : [];
  const srcs = Array.from({ length: COUNT }, (_, i) => {
    const v = i === 0 ? params.src : params[`src${i + 1}`];
    return String(v ?? list[i] ?? "");
  });

  const gap = Math.max(4, base * 0.012);
  const radius = STYLE.sharp ? 0 : base * 0.018;
  // Spread the four entrances over the first ~60% of the layer, capped at 0.6 s apart.
  const stagger = Math.min(fps * 0.6, (total * 0.6) / COUNT);
  const exit = interpolate(f, [total - Math.min(fps * 0.4, total * 0.12), total], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ padding: gap, opacity: exit }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gridTemplateRows: "1fr 1fr",
          gap,
        }}
      >
        {srcs.map((src, i) => {
          const local = f - i * stagger;
          const p = spring({ frame: local, fps, config: { damping: 18, stiffness: 120, mass: 0.8 } });
          const scale = interpolate(p, [0, 1], [0.4, 1]);
          const opacity = interpolate(local, [0, fps * 0.25], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const zoom = interpolate(local, [0, total], [1.15, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          return (
            <div
              key={i}
              style={{
                position: "relative",
                overflow: "hidden",
                borderRadius: radius,
                opacity,
                transform: `scale(${scale})`,
                transformOrigin: ORIGINS[i],
              }}
            >
              {src ? (
                <Img
                  src={src}
                  style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${zoom})` }}
                />
              ) : (
                <div
                  style={{
                    width: "100%",
                    height: "100%",
                    background: COLORS.vellum,
                    border: `${Math.max(2, base * 0.003)}px solid ${COLORS.mutedOnLight}55`,
                    borderRadius: radius,
                    boxSizing: "border-box",
                  }}
                />
              )}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default GrelhaQuatroFotos;

