import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, STYLE, PANEL_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const COUNT = 4;

const GrelhaQuatroImagens: React.FC<PrimitiveProps> = ({ anim, fps, frame }) => {
  const f = useCurrentFrame();
  const params = (anim.params ?? {}) as Record<string, unknown>;
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const base = Math.min(frame.width, frame.height);

  // `src` is the pipeline's slot; src2..src4 (or a srcs array) carry the rest.
  const list = Array.isArray(params.srcs) ? (params.srcs as unknown[]) : [];
  const srcs = Array.from({ length: COUNT }, (_, i) => {
    const v = i === 0 ? params.src : params[`src${i + 1}`];
    return String(v ?? list[i] ?? "");
  });

  const margin = base * 0.05;
  const gap = base * 0.025;
  const radius = STYLE.sharp ? 0 : base * 0.02;
  const stagger = Math.min(fps * 0.45, total * 0.15);
  const exit = interpolate(f, [total - Math.min(fps * 0.4, total * 0.15), total], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ padding: margin, opacity: exit }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gridTemplateRows: "1fr 1fr",
          gap,
        }}
      >
        {srcs.map((src, i) => {
          const local = f - i * stagger;
          const p = spring({ frame: local, fps, config: { damping: 200 }, durationInFrames: Math.round(fps * 0.7) });
          const reveal = interpolate(p, [0, 1], [100, 0]);
          const zoom = interpolate(local, [0, total], [1.18, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.out(Easing.cubic),
          });
          return (
            <div
              key={i}
              style={{
                position: "relative",
                overflow: "hidden",
                borderRadius: radius,
                boxShadow: p > 0.01 ? PANEL_SHADOW : undefined,
                opacity: interpolate(p, [0, 0.3], [0, 1], { extrapolateRight: "clamp" }),
                transform: `scale(${interpolate(p, [0, 1], [0.92, 1])})`,
                clipPath: `inset(0 0 ${reveal}% 0 round ${radius}px)`,
              }}
            >
              {src ? (
                <Img
                  src={src}
                  style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${zoom})` }}
                />
              ) : (
                <div style={{ width: "100%", height: "100%", background: COLORS.vellum }} />
              )}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default GrelhaQuatroImagens;
